<script>
(() => {
  "use strict";
  const hero = document.getElementById("coin-hero");
  const hctx = hero.getContext("2d");
  const work = document.createElement("canvas");
  work.width = 480; work.height = 354;
  const ctx = work.getContext("2d", {alpha:false});
  const W=work.width,H=work.height,CX=W/2,CY=H/2,R=126,DEPTH=14;
  let running=true, start=performance.now(), raf=0;

  function makeFace(front){
    const c=document.createElement("canvas"); c.width=c.height=512;
    const g=c.getContext("2d");
    const grad=g.createRadialGradient(210,175,18,256,256,255);
    grad.addColorStop(0,"#f3d28d");grad.addColorStop(.28,"#c68d3e");
    grad.addColorStop(.72,"#966022");grad.addColorStop(1,"#482912");
    g.fillStyle=grad;g.fillRect(0,0,512,512);

    g.globalAlpha=.18;
    for(let i=0;i<220;i++){
      const a=i*.618, rr=30+(i%170);
      g.strokeStyle=i%3?"#fff1bd":"#4b250d";
      g.lineWidth=.55;
      g.beginPath();g.arc(256,256,rr,0,Math.PI*2);g.stroke();
    }
    g.globalAlpha=1;
    g.strokeStyle="#4b2d12";g.lineWidth=12;g.beginPath();g.arc(256,256,230,0,Math.PI*2);g.stroke();
    g.strokeStyle="#e3b963";g.lineWidth=5;g.beginPath();g.arc(256,256,213,0,Math.PI*2);g.stroke();
    g.strokeStyle="#694016";g.lineWidth=3;g.beginPath();g.arc(256,256,174,0,Math.PI*2);g.stroke();

    if(front){
      g.fillStyle="#513014";g.textAlign="center";g.font="bold 24px Arial";
      g.fillText("WASTEDTOKEN",256,82);g.fillText("MINT · SERIES 001",256,446);
      g.save();g.translate(256,256);
      g.fillStyle="#5c3615";g.strokeStyle="#f2ca78";g.lineWidth=7;
      g.beginPath();
      for(let i=0;i<12;i++){
        const a=-Math.PI/2+i*Math.PI/6,rad=i%2?118:137;
        const x=Math.cos(a)*rad,y=Math.sin(a)*rad;
        i?g.lineTo(x,y):g.moveTo(x,y);
      }
      g.closePath();g.fill();g.stroke();
      g.strokeStyle="#b77a2d";g.lineWidth=5;g.beginPath();g.arc(0,0,104,0,Math.PI*2);g.stroke();
      g.fillStyle="#edc674";g.font="900 102px Georgia";g.fillText("W",0,34);
      g.font="bold 18px Arial";g.letterSpacing="4px";g.fillText("MINT",0,74);
      g.restore();
    }else{
      g.fillStyle="#573415";g.textAlign="center";
      g.font="bold 21px Arial";g.fillText("PROOF OF COMPUTE",256,88);
      g.font="900 75px Georgia";g.fillText("10,000",256,255);
      g.fillStyle="#edc674";g.font="900 34px Arial";g.fillText("TOKENS",256,302);
      g.fillStyle="#573415";g.font="bold 17px Arial";g.fillText("SPENT WITHOUT REGRET",256,420);
      g.strokeStyle="#edc674";g.lineWidth=4;
      for(const y of [174,330]){g.beginPath();g.moveTo(116,y);g.lineTo(396,y);g.stroke()}
      g.beginPath();g.arc(256,256,132,0,Math.PI*2);g.stroke();
    }
    return c;
  }
  const frontFace=makeFace(true),backFace=makeFace(false);
  const frontData=frontFace.getContext("2d").getImageData(0,0,512,512).data;
  const backData=backFace.getContext("2d").getImageData(0,0,512,512).data;

  function mulRyRx(v,ay,ax){
    const sx=Math.sin(ax),cx=Math.cos(ax),sy=Math.sin(ay),cy=Math.cos(ay);
    const x1=v[0],y1=v[1]*cx-v[2]*sx,z1=v[1]*sx+v[2]*cx;
    return [x1*cy+z1*sy,y1,-x1*sy+z1*cy];
  }
  function invRyRx(v,ay,ax){
    const sy=Math.sin(-ay),cy=Math.cos(-ay);
    const x1=v[0]*cy+v[2]*sy,y1=v[1],z1=-v[0]*sy+v[2]*cy;
    const sx=Math.sin(-ax),cx=Math.cos(-ax);
    return [x1,y1*cx-z1*sx,y1*sx+z1*cx];
  }
  function norm(v){const n=Math.hypot(v[0],v[1],v[2])||1;return [v[0]/n,v[1]/n,v[2]/n]}
  function sample(tex,u,v){
    let x=Math.max(0,Math.min(511,(u*511)|0)),y=Math.max(0,Math.min(511,(v*511)|0));
    let q=(y*512+x)*4;return [tex[q],tex[q+1],tex[q+2]];
  }
  function lum(tex,u,v){
    const s=sample(tex,u,v);return (s[0]*.3+s[1]*.55+s[2]*.15)/255;
  }

  function render(t){
    t=((Number(t)||0)%1+1)%1;
    const ay=t*Math.PI*2;
    const ax=t*Math.PI*2 + .18*Math.sin(t*Math.PI*2);
    const img=ctx.createImageData(W,H),d=img.data;

    for(let y=0;y<H;y++)for(let x=0;x<W;x++){
      const i=(y*W+x)*4;
      const dx=x-CX,dy=y-CY;
      const vign=Math.max(0,1-Math.hypot(dx/W,dy/H)*.9);
      d[i]=7+vign*8;d[i+1]=8+vign*8;d[i+2]=8+vign*6;d[i+3]=255;
    }

    const rayD=invRyRx([0,0,1],ay,ax);
    const light=norm([-0.62,-0.68,0.9]);
    const view=[0,0,1];
    const bound=R+DEPTH+8;

    for(let py=Math.floor(CY-bound);py<=Math.ceil(CY+bound);py++){
      for(let px=Math.floor(CX-bound);px<=Math.ceil(CX+bound);px++){
        const worldOrigin=[px-CX,py-CY,-400];
        const o=invRyRx(worldOrigin,ay,ax);
        let best=1e9,kind=-1,hit=null,nlocal=null,faceSign=0;

        if(Math.abs(rayD[2])>1e-7){
          for(const zcap of [-DEPTH,DEPTH]){
            const q=(zcap-o[2])/rayD[2];
            if(q>0&&q<best){
              const xx=o[0]+q*rayD[0],yy=o[1]+q*rayD[1];
              if(xx*xx+yy*yy<=R*R){best=q;kind=0;hit=[xx,yy,zcap];faceSign=zcap>0?1:-1;nlocal=[0,0,faceSign]}
            }
          }
        }
        const A=rayD[0]*rayD[0]+rayD[1]*rayD[1];
        const B=2*(o[0]*rayD[0]+o[1]*rayD[1]);
        const C=o[0]*o[0]+o[1]*o[1]-R*R;
        const disc=B*B-4*A*C;
        if(A>1e-8&&disc>=0){
          const root=Math.sqrt(disc);
          for(const q of [(-B-root)/(2*A),(-B+root)/(2*A)]){
            if(q>0&&q<best){
              const z=o[2]+q*rayD[2];
              if(Math.abs(z)<=DEPTH){best=q;kind=1;hit=[o[0]+q*rayD[0],o[1]+q*rayD[1],z];nlocal=norm([hit[0],hit[1],0])}
            }
          }
        }
        if(kind<0)continue;

        let base,nw;
        if(kind===0){
          let u=hit[0]/(R*2)+.5;
          let v=.5-hit[1]/(R*2);
          if(faceSign<0)u=1-u;
          const tex=faceSign>0?frontData:backData;
          base=sample(tex,u,v);

          const e=1/512;
          const gx=lum(tex,u+e,v)-lum(tex,u-e,v);
          const gy=lum(tex,u,v+e)-lum(tex,u,v-e);
          nlocal=norm([-gx*2.8,gy*2.8,faceSign]);
          nw=norm(mulRyRx(nlocal,ay,ax));
        }else{
          const angle=Math.atan2(hit[1],hit[0]);
          const ridge=.5+.5*Math.sin(angle*92);
          base=[112+ridge*68,67+ridge*38,25+ridge*18];
          let tangent=[-Math.sin(angle),Math.cos(angle),0];
          nlocal=norm([nlocal[0]+tangent[0]*(ridge-.5)*.15,nlocal[1]+tangent[1]*(ridge-.5)*.15,0]);
          nw=norm(mulRyRx(nlocal,ay,ax));
        }

        const ndl=Math.max(0,nw[0]*light[0]+nw[1]*light[1]+nw[2]*light[2]);
        const half=norm([light[0]+view[0],light[1]+view[1],light[2]+view[2]]);
        const spec=Math.pow(Math.max(0,nw[0]*half[0]+nw[1]*half[1]+nw[2]*half[2]),34);
        const rake=Math.pow(Math.max(0,nw[0]*-.9+nw[1]*-.12+nw[2]*.42),10)*.55;
        const shade=.22+.72*ndl;
        const idx=(py*W+px)*4;
        d[idx]=Math.min(255,base[0]*shade+spec*155+rake*90);
        d[idx+1]=Math.min(255,base[1]*shade+spec*140+rake*72);
        d[idx+2]=Math.min(255,base[2]*shade+spec*100+rake*40);
        d[idx+3]=255;
      }
    }
    ctx.putImageData(img,0,0);
    hctx.clearRect(0,0,hero.width,hero.height);
    hctx.imageSmoothingEnabled=true;
    hctx.imageSmoothingQuality="high";
    hctx.drawImage(work,0,0,hero.width,hero.height);
  }

  function animate(now){
    if(!running)return;
    render(((now-start)/9000)%1);
    raf=requestAnimationFrame(animate);
  }

  window.demo={
    canvas:hero,
    setTime(t){render(Math.max(0,Math.min(1,Number(t)||0)));},
    pause(){running=false;cancelAnimationFrame(raf);}
  };
  render(0);
  raf=requestAnimationFrame(animate);

  function drawEdition(canvas,type){
    const g=canvas.getContext("2d"),w=canvas.width,h=canvas.height,cx=w/2,cy=h/2,r=126;
    const colors={
      bronze:["#f0ae5c","#9a5427","#3d1c0e"],
      silver:["#f1f4f2","#8f999a","#343a3a"],
      gold:["#ffe085","#bf8127","#56320c"],
      black:["#6f7371","#171b1a","#050606"]
    }[type];
    g.fillStyle="#0a0b0a";g.fillRect(0,0,w,h);
    g.save();g.translate(cx,cy+6);g.rotate(-.11);
    g.shadowColor=type==="black"?"#000":"rgba(199,136,50,.28)";
    g.shadowBlur=30;g.shadowOffsetY=17;
    g.fillStyle=colors[2];g.beginPath();g.ellipse(0,7,r,r*.93,0,0,Math.PI*2);g.fill();
    g.shadowColor="transparent";
    for(let i=0;i<72;i++){
      const a=i*Math.PI*2/72;
      g.strokeStyle=i%2?colors[0]:colors[2];g.lineWidth=2;
      g.beginPath();g.moveTo(Math.cos(a)*(r-2),Math.sin(a)*(r-2)*.93+7);
      g.lineTo(Math.cos(a)*(r+3),Math.sin(a)*(r+3)*.93+7);g.stroke();
    }
    const q=g.createRadialGradient(-44,-54,6,0,0,r);
    q.addColorStop(0,colors[0]);q.addColorStop(.48,colors[1]);q.addColorStop(1,colors[2]);
    g.fillStyle=q;g.beginPath();g.ellipse(0,0,r-7,(r-7)*.93,0,0,Math.PI*2);g.fill();
    g.strokeStyle=colors[0];g.globalAlpha=.72;g.lineWidth=4;
    g.beginPath();g.ellipse(0,0,r-19,(r-19)*.93,0,0,Math.PI*2);g.stroke();
    g.globalAlpha=.34;g.lineWidth=2;
    g.beginPath();g.ellipse(0,0,r-37,(r-37)*.93,0,0,Math.PI*2);g.stroke();
    g.globalAlpha=1;
    g.fillStyle=colors[2];g.strokeStyle=colors[0];g.lineWidth=4;
    g.beginPath();
    for(let i=0;i<12;i++){
      const a=-Math.PI/2+i*Math.PI/6,rr=i%2?66:76;
      i?g.lineTo(Math.cos(a)*rr,Math.sin(a)*rr*.93):g.moveTo(Math.cos(a)*rr,Math.sin(a)*rr*.93);
    }
    g.closePath();g.fill();g.stroke();
    g.fillStyle=colors[0];g.textAlign="center";g.font="bold 66px Georgia";g.fillText("W",0,22);
    g.font="bold 11px Arial";g.letterSpacing="2px";g.fillText("WASTED TOKEN",0,-91);
    g.fillText(type.toUpperCase()+" EDITION",0,101);
    const shine=g.createLinearGradient(-150,-100,130,100);
    shine.addColorStop(.35,"rgba(255,255,255,0)");
    shine.addColorStop(.49,"rgba(255,255,255,.22)");
    shine.addColorStop(.56,"rgba(255,255,255,0)");
    g.fillStyle=shine;g.beginPath();g.ellipse(0,0,r-8,(r-8)*.93,0,0,Math.PI*2);g.fill();
    g.restore();
  }

